/* Placeholder xlsx.full.min.js
   Minimal stub for XLSX export functionality used by the app. This does NOT implement full xlsx.
   Replace with the official xlsx.full.min.js from cdnjs to enable Excel export features.

   The stub exposes a single util: writeFile, which accepts a Blob and filename and triggers download.
*/
window.XLSX = window.XLSX || {};
(function(X){
  X.writeFile = function(blobData, filename){
    try{
      const blob = new Blob([blobData], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = filename || 'export.xlsx'; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=>URL.revokeObjectURL(url), 1000);
    }catch(e){ console.warn('XLSX.writeFile stub called', e); }
  };
})(window.XLSX);

/* End of placeholder xlsx.full.min.js */